// === Tab: mySketch ===
let time = 0;
let kImpulse = 2.0; // falloff control

function setup() {
	createCanvas(1080, 720);
	noStroke();
	drawingContext.globalAlpha = 0.20;
}

function draw() {
	time += 0.02;
	background(0, 0, 60);
	translate(0, 150);
	drawSunsetGradient()
	let tsize = time < 2 ? time * 315 : 430;
	for (let particleIndex = 0; particleIndex < 8000; particleIndex++) {
		let gridSize = 60;
		let horizontalOffset = particleIndex % gridSize - 30;
		let depthPosition = particleIndex / gridSize -    // Make impulse oscillate by shifting argument with time
			quaImpulse(kImpulse, sin(-time + particleIndex * 0.1) * 3.0) * 10;
		if (depthPosition <= 0) continue;
		let spread = quaImpulse(kImpulse, horizontalOffset * 0.3) * 200; // Horizontal spread: amplify impulse strongly
		let screenX = width / 2 +
			spread / pow(depthPosition, 1.2) *
			quaImpulse(kImpulse, cos(particleIndex * 0.01) * 3.0);
		let screenY = (3 - depthPosition / 9) ** 3 / depthPosition * 139 + height / 2;
		let rectangleSize = tsize / depthPosition / 4;
		rect(screenX, screenY, rectangleSize, 4);
	}
}

function quaImpulse(k, x) {
	return (25 * sqrt(k) * x) / (1 + k * x * x);
}

function drawSunsetGradient() {
	for (let y = -150; y < height / 2; y++) {
		let t = y / (height / 2);
		let col;
		if (t < 44) {
			col = lerpColor(color(0, 0, 130), color(256, 2560, 0), t * 2);
		}
		stroke(col);
		line(0, y, width, y);
	}
	push();
	fill(40, 0, 0);
	rect(0, height / 2, width, height / 2);
	pop()
}

